     1→# ABOUTME: Test for Sea of Nodes IR generation - Chapter 3: Local Variables and SSA Form
     2→# ABOUTME: Validates variable declarations, Store/Load nodes, and SSA properties with scope management
     3→
     4→use v5.42;
     5→use Test::More;
     6→use Test::Deep;
     7→
     8→# Test that we can load the IR modules
     9→use_ok('Chalk::IR::Node');
    10→use_ok('Chalk::IR::Graph');
    11→use_ok('Chalk::IR::Scope');
    12→
    13→# Test Scope basic operations
    14→subtest 'Scope basic operations' => sub {
    15→    my $scope = Chalk::IR::Scope->new();
    16→
    17→    # Should start with one global scope
    18→    is($scope->depth, 1, 'Scope starts with depth 1 (global scope)');
    19→
    20→    # Define a variable in global scope
    21→    $scope->define('$x', 'node_1');
    22→    is($scope->lookup('$x'), 'node_1', 'Can define and lookup variable in global scope');
    23→
    24→    # Push a new scope
    25→    $scope->push_scope();
    26→    is($scope->depth, 2, 'Depth increases after push_scope');
    27→
    28→    # Define same variable in inner scope (shadowing)
    29→    $scope->define('$x', 'node_2');
    30→    is($scope->lookup('$x'), 'node_2', 'Inner scope shadows outer scope');
    31→
    32→    # Define a new variable in inner scope
    33→    $scope->define('$y', 'node_3');
    34→    is($scope->lookup('$y'), 'node_3', 'Can define new variable in inner scope');
    35→
    36→    # Pop inner scope
    37→    $scope->pop_scope();
    38→    is($scope->depth, 1, 'Depth decreases after pop_scope');
    39→    is($scope->lookup('$x'), 'node_1', 'Outer scope variable restored after pop');
    40→    is($scope->lookup('$y'), undef, 'Inner scope variable no longer accessible');
    41→};
    42→
    43→# Test nested scopes
    44→subtest 'Nested scope lookup' => sub {
    45→    my $scope = Chalk::IR::Scope->new();
    46→
    47→    # Define in global scope
    48→    $scope->define('$a', 'node_1');
    49→
    50→    # Push first inner scope
    51→    $scope->push_scope();
    52→    $scope->define('$b', 'node_2');
    53→
    54→    # Push second inner scope
    55→    $scope->push_scope();
    56→    $scope->define('$c', 'node_3');
    57→
    58→    # Should be able to see all three variables
    59→    is($scope->lookup('$a'), 'node_1', 'Can see global scope variable');
    60→    is($scope->lookup('$b'), 'node_2', 'Can see parent scope variable');
    61→    is($scope->lookup('$c'), 'node_3', 'Can see current scope variable');
    62→
    63→    is($scope->depth, 3, 'Depth is 3 with two pushed scopes');
    64→};
    65→
    66→# Test Store node creation
    67→subtest 'Store node creation' => sub {
    68→    my $graph = Chalk::IR::Graph->new();
    69→
    70→    # Create Start node
    71→    my $start = Chalk::IR::Node->new(
    72→        id => 'node_0',
    73→        op => 'Start',
    74→        inputs => [],
    75→        attributes => { function => 'main' }
    76→    );
    77→    $graph->add_node($start);
    78→
    79→    # Create Store node: my $x = 5
    80→    # Store stores a constant value
    81→    my $store = Chalk::IR::Node->new(
    82→        id => 'node_1',
    83→        op => 'Store',
    84→        inputs => ['node_0'],  # Control dependency on Start
    85→        attributes => {
    86→            name => '$x',
    87→            value => { op => 'Constant', value => 5, type => 'Int' }
    88→        }
    89→    );
    90→    $graph->add_node($store);
    91→
    92→    # Verify Store node structure
    93→    my $store_node = $graph->get_node('node_1');
    94→    ok($store_node, 'Store node exists');
    95→    is($store_node->op, 'Store', 'Node op is Store');
    96→    is($store_node->attributes->{name}, '$x', 'Store has variable name');
