# Part 1: Basic parsing tests
subtest 'Basic statement modifier parsing' => sub {
    plan tests => scalar(@test_cases);

    for my $test (@test_cases) {
        my $result = $parser->parse_string($test->{code});
        ok($result, $test->{desc}) or diag("Failed to parse: $test->{code}");
    }
};

# Part 2: IR structure validation tests
subtest 'IR structure validation for statement modifiers' => sub {
    plan tests => 6;

    # Helper to parse and generate IR for a code string
    sub parse_with_ir {
        my ($code) = @_;

        my $graph = Chalk::IR::Graph->new();
        my $scope = Chalk::IR::Scope->new();
        my $builder = Chalk::IR::Builder->new(graph => $graph, scope => $scope);
        my $env = Chalk::Environment->new();
        $env->{ir_builder} = $builder;

        # Create start node
        my $start = $builder->build_start_node('main');
        $builder->set_control($start->id);

        # Create parser with IR environment
        my $ir_parser = Chalk::Parser->new(
            grammar => $chalk_grammar,
            semiring => Chalk::Semiring::Boolean->new(),
            env => $env,
        );

        my $result = $ir_parser->parse_string($code);
        return ($result, $builder, $graph);
    }

    # Test 1: Verify If node exists
    {
        my ($result, $builder, $graph) = parse_with_ir('print("yes") if $x;');
        ok($result, 'Parsing succeeds with IR builder');

        # Find If node in graph
        my $if_node;
        for my $node_id (keys %{$graph->{nodes}}) {
            my $node = $graph->{nodes}{$node_id};
            if ($node->can('op') && $node->op eq 'If') {
                $if_node = $node;
                last;
            }
        }
        ok($if_node, 'If node exists in IR graph') or diag("No If node found in graph");
    }

    # Test 2: Verify IfTrue and IfFalse projection nodes exist
    {
        my ($result, $builder, $graph) = parse_with_ir('print("test") if $condition;');

        my ($if_true, $if_false);
        for my $node_id (keys %{$graph->{nodes}}) {
            my $node = $graph->{nodes}{$node_id};
            next unless $node->can('op') && $node->op eq 'Proj';
            if ($node->can('label') && $node->label eq 'IfTrue') {
                $if_true = $node;
            } elsif ($node->can('label') && $node->label eq 'IfFalse') {
                $if_false = $node;
            }
        }
        ok($if_true, 'IfTrue projection node exists');
        ok($if_false, 'IfFalse projection node exists');
    }

    # Test 3: Verify Region node exists to merge control flow
    {
        my ($result, $builder, $graph) = parse_with_ir('$x = 5 if $flag;');

        my $region_node;
        for my $node_id (keys %{$graph->{nodes}}) {
            my $node = $graph->{nodes}{$node_id};
            if ($node->can('op') && $node->op eq 'Region') {
                $region_node = $node;
                last;
            }
        }
        ok($region_node, 'Region node exists to merge control paths');
    }

    # Test 4: Verify Region has exactly 2 inputs (both control paths)
    {
        my ($result, $builder, $graph) = parse_with_ir('die("error") unless $ok;');

        my $region_node;
        for my $node_id (keys %{$graph->{nodes}}) {
            my $node = $graph->{nodes}{$node_id};
            if ($node->can('op') && $node->op eq 'Region') {
                $region_node = $node;
                last;
            }
        }

        if ($region_node && $region_node->can('inputs')) {
            is(scalar(@{$region_node->inputs}), 2,
               'Region node has exactly 2 control inputs (statement path and passthrough path)');
        } else {
            fail('Could not verify Region inputs');
        }
    }
};

# Part 3: Error case tests
subtest 'Error cases and malformed syntax' => sub {
    plan tests => 3;

    # Test incomplete modifier (missing condition)
    {
        my $result = eval { $parser->parse_string('print if;') };
        my $error = $@;
        # Parse may fail or succeed depending on grammar - document actual behavior
        # For now, just verify it doesn't crash
        ok(defined($result) || $error, 'Handles incomplete conditional modifier without crashing');
    }

    # Test modifier with invalid keyword
    {
        my $result = eval { $parser->parse_string('print when $x;') };
        my $error = $@;
        ok(defined($result) || $error, 'Handles invalid modifier keyword without crashing');
    }

    # Test valid syntax that should parse correctly
    {
        my $result = $parser->parse_string('print("valid") if 1;');
        ok($result, 'Valid modifier with constant condition parses correctly');
    }
};

# Part 4: Verify loop control modifiers work in context
subtest 'Loop control with conditional modifiers' => sub {
    plan tests => 2;

    # These should parse successfully as they're valid Perl
    my $next_result = $parser->parse_string('next if $skip;');
    ok($next_result, 'next if modifier parses successfully');

    my $last_result = $parser->parse_string('last unless $continue;');
    ok($last_result, 'last unless modifier parses successfully');

    # NOTE: Full semantic validation of loop control interaction would require
    # wrapping these in actual loop constructs, which is beyond the scope of
    # pure statement modifier support.
};

done_testing();

