        for my $node_id (keys %{$graph->{nodes}}) {
            my $node = $graph->{nodes}{$node_id};
            if ($node->can('op') && $node->op eq 'If') {
                $if_node = $node;
                last;
            }
        }
        ok($if_node, 'If node exists in IR graph') or diag("No If node found in graph");
    }

